.karir-hero{padding:60px 0 70px;text-align:center;}
.karir-hero h1{font-size:3.4rem;font-weight:800;line-height:1.1;margin-bottom:20px;}
.karir-hero p{font-size:1.15rem;color:#c9c1b2;max-width:580px;margin:0 auto 36px;line-height:1.8;}
.karir-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:20px;margin-bottom:70px;}
.karir-stat{background:linear-gradient(145deg,#251508,#1a1008);border:1px solid #3d2410;border-radius:20px;padding:28px 16px;text-align:center;opacity:0;animation:fadeInUp 0.8s ease forwards;}
.karir-stat:nth-child(1){animation-delay:0.1s;}.karir-stat:nth-child(2){animation-delay:0.2s;}.karir-stat:nth-child(3){animation-delay:0.3s;}.karir-stat:nth-child(4){animation-delay:0.4s;}
.karir-stat .num{font-size:2.4rem;font-weight:800;background:linear-gradient(145deg,#f5e18c,#d4af37);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;}
.karir-stat .lbl{font-size:0.85rem;color:#9c927e;margin-top:4px;}
.loker-grid{display:flex;flex-direction:column;gap:20px;margin-top:40px;}
.loker-card{background:linear-gradient(145deg,#251508,#1a1008);border:1px solid #3d2410;border-radius:24px;padding:28px 32px;display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap;transition:0.35s;box-shadow:0 6px 0 #120b04;opacity:0;animation:fadeInUp 0.8s ease forwards;}
.loker-card:nth-child(1){animation-delay:0.1s;}.loker-card:nth-child(2){animation-delay:0.2s;}.loker-card:nth-child(3){animation-delay:0.3s;}.loker-card:nth-child(4){animation-delay:0.4s;}.loker-card:nth-child(5){animation-delay:0.5s;}
.loker-card:hover{border-color:var(--gold-dark);transform:translateY(-6px);box-shadow:0 20px 40px rgba(0,0,0,0.6);}
.loker-icon{background:rgba(212,175,55,0.08);border:1px solid rgba(212,175,55,0.2);border-radius:16px;width:56px;height:56px;display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:1.5rem;color:var(--gold);}
.loker-info{flex:1 1 200px;}
.loker-info h3{font-size:1.2rem;color:#f0ece4;margin-bottom:6px;}
.loker-info .loker-meta{display:flex;flex-wrap:wrap;gap:10px;margin-top:8px;}
.loker-tag{font-size:0.78rem;padding:3px 12px;border-radius:40px;font-weight:600;letter-spacing:0.5px;}
.tag-dept{background:rgba(183,28,28,0.2);color:#f5a5a5;border:1px solid rgba(183,28,28,0.3);}
.tag-type{background:rgba(212,175,55,0.1);color:#f5e18c;border:1px solid rgba(212,175,55,0.25);}
.tag-loc{background:rgba(255,255,255,0.05);color:#b8ae9a;border:1px solid rgba(255,255,255,0.1);}
.loker-card .btn-primary{flex-shrink:0;padding:10px 26px;font-size:0.9rem;}
.benefit-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:24px;margin-top:40px;}
.benefit-card{background:linear-gradient(145deg,#251508,#1a1008);border:1px solid #3d2410;border-radius:24px;padding:30px 22px;text-align:center;transition:0.35s;box-shadow:0 6px 0 #120b04;opacity:0;animation:fadeInUp 0.8s ease forwards;}
.benefit-card:nth-child(1){animation-delay:0.1s;}.benefit-card:nth-child(2){animation-delay:0.2s;}.benefit-card:nth-child(3){animation-delay:0.3s;}.benefit-card:nth-child(4){animation-delay:0.4s;}.benefit-card:nth-child(5){animation-delay:0.5s;}.benefit-card:nth-child(6){animation-delay:0.6s;}
.benefit-card:hover{border-color:var(--gold-dark);transform:translateY(-8px);box-shadow:0 20px 40px rgba(0,0,0,0.6);}
.benefit-card i{font-size:2.2rem;color:var(--gold);background:rgba(212,175,55,0.08);padding:14px;border-radius:50%;display:inline-block;margin-bottom:16px;}
.benefit-card h4{font-size:1.05rem;color:#f0ece4;margin-bottom:8px;}
.benefit-card p{font-size:0.88rem;color:#9c927e;line-height:1.6;}
.sdm-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:28px;margin-top:40px;}
.sdm-card{background:linear-gradient(145deg,#251508,#1a1008);border:1px solid #3d2410;border-radius:28px;padding:32px 26px;transition:0.4s;box-shadow:0 8px 0 #120b04;opacity:0;animation:fadeInUp 0.8s ease forwards;}
.sdm-card:nth-child(1){animation-delay:0.15s;}.sdm-card:nth-child(2){animation-delay:0.3s;}.sdm-card:nth-child(3){animation-delay:0.45s;}
.sdm-card:hover{border-color:var(--gold-dark);transform:translateY(-10px);box-shadow:0 24px 48px rgba(0,0,0,0.7);}
.sdm-num{font-size:3rem;font-weight:900;background:linear-gradient(145deg,#f5e18c,#d4af37);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;line-height:1;margin-bottom:14px;}
.sdm-card h3{font-size:1.3rem;color:#f0ece4;margin-bottom:10px;}
.sdm-card p{font-size:0.92rem;color:#b8ae9a;line-height:1.75;}
.sdm-card ul{margin-top:14px;padding-left:0;list-style:none;display:flex;flex-direction:column;gap:8px;}
.sdm-card ul li{font-size:0.88rem;color:#c9c1b2;display:flex;align-items:center;gap:8px;}
.sdm-card ul li::before{content:'';width:6px;height:6px;border-radius:50%;background:var(--gold);flex-shrink:0;}
.form-lamar{background:linear-gradient(145deg,#251508,#1a1008);border:1px solid rgba(212,175,55,0.25);border-radius:32px;padding:48px 40px;margin-top:10px;opacity:0;animation:fadeInUp 0.8s ease 0.3s forwards;}
.form-lamar h3{font-size:1.8rem;font-weight:700;margin-bottom:8px;color:#f0ece4;}
.form-lamar p{color:#9c927e;margin-bottom:32px;font-size:0.95rem;}
.form-row{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-bottom:18px;}
.form-group{display:flex;flex-direction:column;gap:7px;}
.form-group.full{grid-column:1/-1;}
.form-group label{font-size:0.85rem;color:#b8ae9a;letter-spacing:0.5px;}
.form-group input,.form-group select,.form-group textarea{background:rgba(255,255,255,0.04);border:1px solid #3d2410;border-radius:12px;padding:12px 16px;color:#f0ece4;font-size:0.95rem;outline:none;transition:0.3s;font-family:inherit;}
.form-group input:focus,.form-group select:focus,.form-group textarea:focus{border-color:var(--gold-dark);background:rgba(212,175,55,0.05);box-shadow:0 0 0 3px rgba(212,175,55,0.08);}
.form-group select option{background:#251508;}
.form-group textarea{resize:vertical;min-height:110px;}
@media(max-width:768px){.karir-hero h1{font-size:2.4rem;}.form-row{grid-template-columns:1fr;}.loker-card{flex-direction:column;align-items:flex-start;}.form-lamar{padding:28px 20px;}}
